"use client";
import React, { useState, useEffect, useRef } from 'react';
import { 
  X, Send, Bot, Sparkles, HeartPulse, Shield, Activity, 
  AlertCircle, PhoneCall, CheckCircle2 
} from 'lucide-react';

// ... (CLINIC_CONTEXT and SERVICES_DATA stay the same as above)

export default function BaviSmartUI() {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState([
    { role: 'bot', text: "Hello! I'm Bavi 🦫. How is your health journey going today?" }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [sentiment, setSentiment] = useState<'neutral' | 'urgent' | 'happy'>('neutral');
  const scrollRef = useRef<HTMLDivElement>(null);

  // --- REFINED GEMINI CALL WITH SENTIMENT ---
  const askGemini = async (userPrompt: string) => {
    const GEMINI_API_KEY = process.env.NEXT_PUBLIC_GEMINI_API_KEY;
    const API_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${GEMINI_API_KEY}`;

    const systemInstruction = `
      You are Bavi for Beavers FamilyCare. 
      CRITICAL: You must end every response with a sentiment tag in brackets: [URGENT], [HAPPY], or [NEUTRAL].
      Use [URGENT] if the user is in pain, has an emergency, or is angry.
      Use [HAPPY] if the user says thank you or feels better.
      Location: Ngong, Nairobi, El Paso.
    `;

    try {
      const response = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ parts: [{ text: `${systemInstruction}\n\nUser: ${userPrompt}` }] }]
        })
      });

      const data = await response.json();
      const rawText = data.candidates[0].content.parts[0].text;

      // Logic to strip the tag and set the UI state
      if (rawText.includes('[URGENT]')) setSentiment('urgent');
      else if (rawText.includes('[HAPPY]')) setSentiment('happy');
      else setSentiment('neutral');

      return rawText.replace(/\[URGENT\]|\[HAPPY\]|\[NEUTRAL\]/g, "").trim();
    } catch (error) {
      return "I'm having trouble connecting. Please call +254 700 000 000.";
    }
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;
    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsTyping(true);

    const aiResponse = await askGemini(userMsg);
    setMessages(prev => [...prev, { role: 'bot', text: aiResponse }]);
    setIsTyping(false);
  };

  // --- DYNAMIC STYLING BASED ON SENTIMENT ---
  const getHeaderColor = () => {
    if (sentiment === 'urgent') return 'bg-red-600 animate-pulse';
    if (sentiment === 'happy') return 'bg-emerald-600';
    return 'bg-[#0f172a]'; // Default Slate
  };

  return (
    <div className="fixed bottom-6 left-6 z-[9999] font-sans">
      <button onClick={() => setIsOpen(!isOpen)} className="bg-[#2563eb] text-white p-4 rounded-2xl shadow-2xl flex items-center gap-2">
        <Bot size={24} /> <span className="font-bold">Chat with Bavi</span>
      </button>

      {isOpen && (
        <div className="absolute bottom-20 left-0 w-[380px] h-[600px] bg-white rounded-[2rem] shadow-2xl border border-slate-200 flex flex-col overflow-hidden animate-in slide-in-from-bottom-5 duration-500">
          
          {/* DYNAMIC HEADER */}
          <div className={`${getHeaderColor()} p-6 text-white transition-colors duration-500 relative`}>
            <div className="flex items-center justify-between relative z-10">
              <div className="flex items-center gap-3">
                <div className="bg-white/20 p-2 rounded-xl backdrop-blur-md">
                  {sentiment === 'urgent' ? <AlertCircle size={22}/> : <Sparkles size={22}/>}
                </div>
                <div>
                  <p className="font-black text-2xl tracking-tighter">Bavi 🦫</p>
                  <p className="text-[10px] opacity-80 uppercase font-bold tracking-widest">
                    {sentiment === 'urgent' ? 'Emergency Protocol Active' : 'Digital Concierge'}
                  </p>
                </div>
              </div>
              {sentiment === 'happy' && <CheckCircle2 size={24} className="text-emerald-200" />}
            </div>
          </div>

          {/* MESSAGES AREA */}
          <div ref={scrollRef} className="flex-1 p-5 overflow-y-auto space-y-6 bg-[#f8fafc]">
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-[15px] shadow-sm ${
                  m.role === 'user' ? 'bg-[#2563eb] text-white' : 'bg-white text-slate-800 border'
                }`}>
                  {m.text}
                  {/* URGENT CALL BUTTON ACTION */}
                  {sentiment === 'urgent' && m.role === 'bot' && (
                    <button className="mt-3 w-full bg-red-100 text-red-600 py-2 rounded-lg font-bold flex items-center justify-center gap-2 hover:bg-red-200 transition-colors">
                      <PhoneCall size={16} /> Call Hotline Now
                    </button>
                  )}
                </div>
              </div>
            ))}
            {isTyping && <div className="text-xs font-bold text-blue-500 ml-2 animate-bounce">Bavi is thinking...</div>}
          </div>

          <form onSubmit={handleSend} className="p-4 bg-white border-t flex gap-2">
            <input 
              className="flex-1 bg-slate-100 px-4 py-3 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 font-semibold" 
              placeholder="How can we help today?"
              value={input}
              onChange={(e) => setInput(e.target.value)}
            />
            <button type="submit" className="bg-[#0f172a] text-white p-3 rounded-xl hover:bg-blue-600 transition-all">
              <Send size={20} />
            </button>
          </form>
        </div>
      )}
    </div>
  );
}